// supplier_payment_documents.ts — the supplier's invoice and receipt for a payment to QuotesDone
// (the annual listing fee, or the settlement of outstanding charges), on the QuotesDone template
// (pdf_native render.ts + doc_template.ts), in English and in full Arabic.
//
// 22 Sep 2026, seats: sales_engineer (the document) and accountant (the payment). Audit of every
// document we issue, finding 2 (HIGH). The founder (instructions 568, 569): "not a single pdf should be
// generated by our team unless its as per our template"; no third-party PDF is sent as ours. What a
// supplier had for a payment was (a) Stripe's own invoice, because supplier_pay turned
// invoice_creation on for both checkouts, and (b) a one-table "Payment receipt" with ISO dates, no
// signature, no stamp, no VAT statement and a line telling the supplier to expect Stripe's invoice.
// Both supplier checkouts now create no Stripe invoice; THESE are the documents.
//
// Modelled on the customer's reveal-fee invoice and receipt (reveal_fee_documents.ts): the same
// compact cover, parties, charges table, totals, "not subject to VAT" line, signature and stamp. No TRN
// because there is none: QuotesDone is not VAT-registered (founder, 14 Sep 2026; DET 1633275), so the
// document is an "Invoice", never a "Tax Invoice". Dates print as "06 Sep 2026" (the audit's ruling for
// these documents); amounts as "AED 1,250.00" / "1,250.00 درهم".
//
// Pure: a payment record in, renderer bodies out. No I/O. Prevented from regressing by
// supabase/functions/pdf_native/every_document_we_issue.test.ts and scripts/checks/every_pdf_we_issue_is_on_our_template.mjs.
import { money } from './supplier_charge.ts';
import { ISSUER, NO_VAT } from './reveal_fee_documents.ts';

export type Lang = 'en' | 'ar';
export const SUPPLIER_PAY_DOC_VERSION = 's1';

export type SupplierPayment = {
  kind: 'registration' | 'dues';
  /** Our own document number: QD-REG-<lead>-<year paid> (one listing fee a year) or QD-DU-<first due id of the payment>. */
  ref: string;
  paid_at: string;
  payment_ref: string;
  supplier: { name: string; email: string | null };
  /** Registration: the year the fee covers. */
  period?: { from: string; to: string } | null;
  /** Dues: the settled charges, each already in AED. */
  lines: { en: string; ar: string; amount: number }[];
  total: number;
};

const MON_EN = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const MON_AR = ['يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو', 'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'];
/** "06 Sep 2026" / "06 سبتمبر 2026" (Western digits in both, as every amount on the page). */
export function shortDate(iso: string, lang: Lang): string {
  const [y, m, d] = String(iso).slice(0, 10).split('-').map(Number);
  return `${String(d).padStart(2, '0')} ${(lang === 'ar' ? MON_AR : MON_EN)[m - 1]} ${y}`;
}

/** The dues' charge lines, from supplier_dues rows (what supplier_api reads). */
// deno-lint-ignore no-explicit-any
export function duesLines(rows: any[]): SupplierPayment['lines'] {
  const sum = (k: string) => Math.round(rows.reduce((a, d) => a + Number(d[k] || 0), 0) * 100) / 100;
  const out: SupplierPayment['lines'] = [
    // supplier_dues.amount_due is the clause 33 non-response charge: the refund and, from Supplier Agreement v14, the
    // processor fee QuotesDone could not recover (fn_accountant_nonresponse_charge charge_aed, 24 Sep 2026).
    { en: 'Non-response charge: the refund to the customer (and, from Supplier Agreement v14, the processor fee not recovered)', ar: 'رسم عدم الاستجابة: المبلغ المردود للعميل (ومنذ الإصدار v14 من اتفاقية المورّد، رسوم مزوّد خدمة الدفع غير المستردّة)', amount: sum('amount_due') },
    { en: 'Administration fee', ar: 'الرسوم الإدارية', amount: sum('admin_fee') },
  ];
  const interest = Math.round((sum('interest_amount') + sum('fine_amount')) * 100) / 100;
  if (interest > 0) out.push({ en: 'Interest and fines accrued', ar: 'الفوائد والغرامات المستحقة', amount: interest });
  return out.filter((l) => l.amount > 0);
}

// deno-lint-ignore no-explicit-any
type Block = Record<string, any>;
function what(p: SupplierPayment, lang: Lang) {
  const ar = lang === 'ar';
  if (p.kind === 'registration') {
    const per = p.period ? (ar ? ` (${shortDate(p.period.from, 'ar')} إلى ${shortDate(p.period.to, 'ar')})` : ` (${shortDate(p.period.from, 'en')} to ${shortDate(p.period.to, 'en')})`) : '';
    // The name comes from the signed Supplier Agreement v12 clause 2 ('Subscription Fee' / «رسوم الاشتراك»), not
    // from this file. It was a THIRD name for the same fee, printed on the tax document the supplier files
    // (review of #858, 22 Sep 2026). scripts/checks/one_fee_has_one_name.test.mjs holds it to the agreement.
    return ar ? `رسوم الاشتراك السنوية للمورّد على QuotesDone${per}` : `QuotesDone annual supplier Subscription Fee${per}`;
  }
  return ar ? 'تسوية الرسوم المستحقة بموجب اتفاقية المورّد' : 'Settlement of outstanding charges under the Supplier Agreement';
}
function charges(p: SupplierPayment, lang: Lang): Block {
  const ar = lang === 'ar';
  const cents = (n: number) => Math.round(n * 100);
  // The lines must add up to what was paid, or the document is not issued at all.
  if (p.lines.reduce((a, l) => a + cents(l.amount), 0) !== cents(p.total)) throw new Error(`lines do not add up to ${p.total}`);
  return { t: 'table', head: ar ? ['#', 'البيان', 'المبلغ'] : ['#', 'Description', 'Amount'],
    rows: p.lines.map((l, i) => [String(i + 1), ar ? l.ar : l.en, money(l.amount, lang)]), widths: [0.06, 0.7, 0.24], align: ['c', 's', 'e'] };
}
function parties(p: SupplierPayment, lang: Lang, toLabel: string): Block {
  const ar = lang === 'ar', co = ISSUER[lang];
  return { t: 'kv', pairs: [[ar ? 'من' : 'From', `${co.name} · ${co.licence}`], [toLabel, [p.supplier.name, p.supplier.email].filter(Boolean).join(' · ')]] };
}
function body(p: SupplierPayment, lang: Lang, kind: 'invoice' | 'receipt', title: string, kicker: string, meta: string[][], blocks: Block[]) {
  const ar = lang === 'ar';
  return {
    lang, ref: p.ref, name: `${kind}-${p.ref}-${lang}-${SUPPLIER_PAY_DOC_VERSION}`, title,
    cover: { kicker, title, subtitle: what(p, lang), meta, figures: [], compact: true },
    control: `${p.ref} · ${SUPPLIER_PAY_DOC_VERSION} · ${ar ? 'أُصدر في' : 'Issued'} ${shortDate(p.paid_at, lang)} · ${ar ? 'أعدّه محاسب QuotesDone' : 'Prepared by the QuotesDone accountant'}`,
    blocks, options: { letterhead: true, sign: true, stamp: true },
    ...(ar ? { date_ar: shortDate(p.paid_at, 'ar') } : { date: shortDate(p.paid_at, 'en') }),
  };
}
const METHOD = { en: 'Card, via Stripe', ar: 'بطاقة عبر Stripe' };
const ONLY = {
  en: 'This is the only invoice QuotesDone issues for this payment. Our payment processor, Stripe, does not issue one.',
  ar: 'هذه هي الفاتورة الوحيدة التي تصدرها QuotesDone عن هذه الدفعة، ولا يصدر معالج الدفع Stripe فاتورة عنها.',
};

export function supplierInvoiceDocument(p: SupplierPayment, lang: Lang) {
  const ar = lang === 'ar', T = (en: string, a: string) => ar ? a : en, paid = shortDate(p.paid_at, lang);
  return body(p, lang, 'invoice', T('Invoice', 'فاتورة'), T('Invoice — paid — not subject to VAT', 'فاتورة — مدفوعة — غير خاضعة لضريبة القيمة المضافة'),
    [[T('Invoice no.', 'رقم الفاتورة'), p.ref], [T('Invoice date', 'تاريخ الفاتورة'), paid], [T('Status', 'الحالة'), T('PAID', 'مدفوعة')], [T('Amount', 'المبلغ'), money(p.total, lang)]],
    [
      parties(p, lang, T('Billed to', 'صادرة إلى')),
      { t: 'section', n: 1, text: T('Charges', 'تفاصيل المبلغ') }, charges(p, lang),
      { t: 'totals', rows: [[T('Total', 'الإجمالي'), money(p.total, lang), false], [T(`Paid on ${paid}`, `المدفوع بتاريخ ${paid}`), '− ' + money(p.total, lang), false], [T('Balance due', 'الرصيد المستحق'), money(0, lang), true]], note: '' },
      { t: 'note', text: NO_VAT[lang] },
      { t: 'kv', pairs: [[T('Paid by', 'طريقة الدفع'), METHOD[lang]], [T('Payment reference', 'مرجع الدفع'), p.payment_ref]] },
      { t: 'note', text: ONLY[lang] },
    ]);
}

export function supplierReceiptDocument(p: SupplierPayment, lang: Lang) {
  const ar = lang === 'ar', T = (en: string, a: string) => ar ? a : en, paid = shortDate(p.paid_at, lang);
  return body(p, lang, 'receipt', T('Payment Receipt', 'إيصال دفع'), T('Receipt — payment received — not subject to VAT', 'إيصال — تم استلام الدفعة — غير خاضع لضريبة القيمة المضافة'),
    [[T('For invoice no.', 'عن الفاتورة رقم'), p.ref], [T('Date received', 'تاريخ الاستلام'), paid], [T('Amount received', 'المبلغ المستلَم'), money(p.total, lang)], [T('Status', 'الحالة'), T('PAID', 'مدفوعة')]],
    [
      parties(p, lang, T('Received from', 'استُلم من')),
      { t: 'section', n: 1, text: T('Payment for', 'مقابل') }, charges(p, lang),
      { t: 'totals', rows: [[T('Total received', 'إجمالي المبلغ المستلَم'), money(p.total, lang), true]], note: '' },
      { t: 'kv', pairs: [[T('Paid by', 'طريقة الدفع'), METHOD[lang]], [T('Payment reference', 'مرجع الدفع'), p.payment_ref]] },
      { t: 'note', text: T(`This receipt confirms payment in full of invoice ${p.ref}. It is not a second invoice. `, `يؤكد هذا الإيصال سداد الفاتورة رقم ${p.ref} بالكامل، وهو ليس فاتورة ثانية. `) + NO_VAT[lang] },
    ]);
}
